def update_pheromone(tau, tours, lens, rho):
    new = (1 - rho) * tau                                  # випаровування (нова матриця, tau не змінюємо)
    for g, L in zip(tours, lens):
        t = np.concatenate(([0], g, [0]))                  # додаємо вокзал на початку і в кінці
        np.add.at(new, (t[:-1], t[1:]), 1.0 / L)           # поповнення на напрямлених ребрах i -> j
    return new
